-- 0040: Karobar-style staff job titles (Partner, Manager, Accountant, Sales Person, Stock Manager, Entry Person). Needs 0039. Safe to re-run.
-- A title sits on top of an existing security role (admin / accountant / staff), so every existing role check keeps working.
ALTER TABLE public.business_memberships ADD COLUMN IF NOT EXISTS job_title text;
ALTER TABLE public.business_invitations ADD COLUMN IF NOT EXISTS job_title text;
ALTER TABLE public.business_memberships DROP CONSTRAINT IF EXISTS business_memberships_job_title_check;
ALTER TABLE public.business_memberships ADD CONSTRAINT business_memberships_job_title_check CHECK (job_title IS NULL OR job_title IN ('partner','manager','accountant','sales_person','stock_manager','entry_person'));
ALTER TABLE public.business_invitations DROP CONSTRAINT IF EXISTS business_invitations_job_title_check;
ALTER TABLE public.business_invitations ADD CONSTRAINT business_invitations_job_title_check CHECK (job_title IS NULL OR job_title IN ('partner','manager','accountant','sales_person','stock_manager','entry_person'));

-- Default "unticked" permissions per title (generated from src/lib/job-titles.ts).
CREATE TABLE IF NOT EXISTS public.job_title_denials(job_title text NOT NULL, permission text NOT NULL, PRIMARY KEY(job_title,permission));
REVOKE ALL ON public.job_title_denials FROM PUBLIC,anon,authenticated; GRANT ALL ON public.job_title_denials TO service_role;
ALTER TABLE public.job_title_denials ENABLE ROW LEVEL SECURITY;
DELETE FROM public.job_title_denials;
