CREATE OR REPLACE FUNCTION public.job_title_role(_title text) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT CASE _title WHEN 'partner' THEN 'admin' WHEN 'manager' THEN 'accountant' WHEN 'accountant' THEN 'accountant' WHEN 'sales_person' THEN 'staff' WHEN 'stock_manager' THEN 'staff' WHEN 'entry_person' THEN 'staff' END $$;

-- Change a member's title: sets the matching security role (same authority rules as update_business_member) and applies the title's default permissions.
CREATE OR REPLACE FUNCTION public.set_member_job_title(_business uuid,_user uuid,_title text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE st text;
BEGIN
 IF public.job_title_role(_title) IS NULL THEN RAISE EXCEPTION 'Unknown role'; END IF;
 SELECT status INTO st FROM public.business_memberships WHERE business_id=_business AND user_id=_user;
 IF st IS NULL THEN RAISE EXCEPTION 'Member not found'; END IF;
 PERFORM public.update_business_member(_business,_user,public.job_title_role(_title),st);
 UPDATE public.business_memberships SET job_title=_title WHERE business_id=_business AND user_id=_user;
 DELETE FROM public.member_permission_denials WHERE business_id=_business AND user_id=_user;
 INSERT INTO public.member_permission_denials(business_id,user_id,permission,granted_by) SELECT _business,_user,permission,auth.uid() FROM public.job_title_denials WHERE job_title=_title;
 PERFORM public.write_audit(_business,'job_title.update','business_memberships',_user::text,NULL,jsonb_build_object('title',_title));
END $$;
REVOKE ALL ON FUNCTION public.set_member_job_title(uuid,uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.set_member_job_title(uuid,uuid,text) TO authenticated;

-- Remember the title chosen on an invitation (admin only, invitation must still be open).
CREATE OR REPLACE FUNCTION public.set_invitation_job_title(_business uuid,_invitation uuid,_title text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
 IF COALESCE(public.business_role_rank(_business,auth.uid()),0)<80 THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF;
 UPDATE public.business_invitations SET job_title=_title WHERE id=_invitation AND business_id=_business AND accepted_at IS NULL AND revoked_at IS NULL AND role_code=public.job_title_role(_title);
END $$;
REVOKE ALL ON FUNCTION public.set_invitation_job_title(uuid,uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.set_invitation_job_title(uuid,uuid,text) TO authenticated;

-- When an invitation is accepted, give the new member the invited title and its default permissions.
CREATE OR REPLACE FUNCTION public.apply_invited_job_title() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE t text;
BEGIN
 SELECT i.job_title INTO t FROM public.business_invitations i JOIN auth.users u ON lower(u.email)=i.email
  WHERE i.business_id=NEW.business_id AND u.id=NEW.user_id AND i.job_title IS NOT NULL AND i.accepted_at IS NULL AND i.revoked_at IS NULL AND i.role_code=NEW.role_code ORDER BY i.expires_at DESC LIMIT 1;
 IF t IS NULL THEN RETURN NEW; END IF;
 UPDATE public.business_memberships SET job_title=t WHERE business_id=NEW.business_id AND user_id=NEW.user_id;
 INSERT INTO public.member_permission_denials(business_id,user_id,permission,granted_by) SELECT NEW.business_id,NEW.user_id,permission,COALESCE(NEW.invited_by,NEW.user_id) FROM public.job_title_denials WHERE job_title=t ON CONFLICT DO NOTHING;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION public.apply_invited_job_title() FROM PUBLIC,anon,authenticated;
DROP TRIGGER IF EXISTS apply_invited_job_title ON public.business_memberships;
CREATE TRIGGER apply_invited_job_title AFTER INSERT ON public.business_memberships FOR EACH ROW EXECUTE FUNCTION public.apply_invited_job_title();
